from bs4 import BeautifulSoup
import requests

def scrape_catalogue_page(page_number):
    url = f"/catalogue?page={page_number}"
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
    }

    response = requests.get(url, headers=headers)
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    container = soup.find(id="item-grid")

    if not container:
        return []

    rows = []
    for card in container.find_all(class_="item-card"):
        sku = card.find(class_="sku")
        title = card.find(class_="title")
        price = card.find(class_="price")

        if sku and title and price:
            rows.append({
                "sku": sku.get_text(strip=True),
                "title": title.get_text(strip=True),
                "price": price.get_text(strip=True)
            })

    return rows

if __name__ == "__main__":
    results = scrape_catalogue_page(2)
    for row in results:
        print(f"{row['sku']}, {row['title']}, {row['price']}")
